async function startPerformance(info){await Promise.all([waitForPuppets(),waitForBackgrounds(acts)]);await waitForSpeechVoices();renderTimeline();$('#coverage').textContent=`${info.shortened?'Story shortened toward 8 minutes · ':''}${info.coverage??100}% of story retained`;$('#voiceInfo').textContent=speechUnavailable?'VOICE UNAVAILABLE · PACED SHOW':'BROWSER VOICE';setLoading(false);$('#stageOverlay').classList.add('hidden');$('#generate').disabled=true;$('#playPause').disabled=false;$('#playPause').textContent='Ⅱ';setStatus('generating','PUPPET SHOW PLAYING');await new Promise(resolve=>setTimeout(resolve,80));playing=true;elapsed=0;frameClock=0;activeActIndex=-1;raf=requestAnimationFrame(performanceFrame);for(let i=0;i<acts.length;i++){while(!playing)await new Promise(resolve=>setTimeout(resolve,50));activeActIndex=i;actStartElapsed=elapsed;acts[i].seconds=Math.max(acts[i].seconds,acts[i].movement.seconds);renderTimeline(i);await speakAct(acts[i]);const finishAt=Math.max(acts[i].seconds,(acts[i].actionOffset||0)+acts[i].movement.seconds);while(elapsed-actStartElapsed<finishAt)await new Promise(resolve=>setTimeout(resolve,35));acts[i].seconds=Math.max(finishAt,elapsed-actStartElapsed);runTime=acts.reduce((sum,act)=>sum+act.seconds,0);activeActIndex=-1}playing=false;window.speechSynthesis?.cancel();cancelAnimationFrame(raf);runTime=acts.reduce((sum,act)=>sum+act.seconds,0);drawStage(Math.max(0,runTime-.02),true);$('#playPause').textContent='✓';$('#playPause').disabled=true;$('#generate').disabled=false;$('#generate').querySelector('small').textContent='Create another continuous show';$('#voiceInfo').textContent=speechUnavailable?'VOICE UNAVAILABLE · PACED SHOW':'BROWSER VOICE · FINISHED';$('#playerProgress').style.width='100%';$('#playerTime').textContent=`${formatTime(runTime)} / ${formatTime(runTime)}`;setStatus('ready',speechUnavailable?'SHOW FINISHED · NARRATION PACED':'SHOW FINISHED · SPEECH STOPPED')}
